def most_common_char(s):
    if not s:
        raise ValueError('string must be non-empty')
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1

    # Find the maximum count
    max_count = 0
    for count in counts.values():
        if count > max_count:
            max_count = count

    # Find all characters with the maximum count
    most_common_chars = []
    for ch, count in counts.items():
        if count == max_count:
            most_common_chars.append(ch)

    # Return the lexicographically smallest character among the most common ones
    return min(most_common_chars)
